insert into sources (id, name, kind, home_url, terms_url, can_ingest, can_link_out, legal_basis, ingest_blocked_by) values ('doorway', 'Doorway Housing Portal (BAHFA)', 'official_portal', 'https://housingbayarea.mtc.ca.gov/', 'https://mtc.ca.gov/doorway-housing-portal-terms-use', false, true, 'Doorway Terms of Use license non-automated, non-commercial use and prohibit scraping, bots, bulk feeds and republishing without prior written authorization from the Agencies. We link out only.', 'Written data-sharing authorization from BAHFA/MTC (Doorway runs on the open-source Bloom Housing platform, which has a listings API, but using Doorway''s instance requires permission).') on conflict (id) do update set legal_basis = excluded.legal_basis, can_ingest = excluded.can_ingest, ingest_blocked_by = excluded.ingest_blocked_by;
insert into sources (id, name, kind, home_url, terms_url, can_ingest, can_link_out, legal_basis, ingest_blocked_by) values ('211-alameda', '211 Alameda County', 'official_referral', 'https://211alamedacounty.org/find-help-information/alameda-county-housing/', null, false, true, 'Referral service. We show its public phone/text lines and link to its housing page. No data feed is published.', 'A data partnership with Eden I&R (operator of 211 Alameda County).') on conflict (id) do update set legal_basis = excluded.legal_basis, can_ingest = excluded.can_ingest, ingest_blocked_by = excluded.ingest_blocked_by;
