insert into sources (id, name, kind, home_url, terms_url, can_ingest, can_link_out, legal_basis, ingest_blocked_by) values ('apartments-com', 'Apartments.com', 'aggregator', 'https://www.apartments.com/', null, false, true, 'Link-out only. No public listings API; automated collection is not permitted.', 'A licensing agreement with CoStar (Apartments.com).') on conflict (id) do update set legal_basis = excluded.legal_basis, can_ingest = excluded.can_ingest, ingest_blocked_by = excluded.ingest_blocked_by;
