insert into programs (id, regions, name, operator, kind, url, phone, tty, hours, what_it_is, waitlist_info, eligibility_info, vacancy_info, checked_on, sources) values ('doorway', array['bay_area']::text[], 'Doorway Housing Portal', 'Bay Area Housing Finance Authority (BAHFA)', 'affordable_portal', 'https://housingbayarea.mtc.ca.gov/', null, null, null, 'The Bay Area''s official portal for affordable rental listings across the nine counties.', 'Listings are run as lotteries, waitlists or first-come-first-served. Each listing says which.', 'Each listing sets its own income limits and rules. Doorway helps you check eligibility before applying.', 'Listings are housing opportunities. Being listed does not guarantee acceptance or an immediate vacancy.', '2026-11-01', array['https://housingbayarea.mtc.ca.gov/housing-basics']::text[]) on conflict (id) do nothing;
insert into programs (id, regions, name, operator, kind, url, phone, tty, hours, what_it_is, waitlist_info, eligibility_info, vacancy_info, checked_on, sources) values ('211-alameda', array['bay_area']::text[], '211 Alameda County', 'Eden I&R', 'referral_line', 'https://211alamedacounty.org/find-help-information/alameda-county-housing/', '211', null, null, 'Free referral line for housing help, shelter and county services. You can also text 898211.', 'Referrals, not applications.', 'Depends on the program you''re referred to.', 'Shelter availability is posted on its site. It doesn''t list individual rental vacancies.', '2026-11-01', array['https://211alamedacounty.org/find-help-information/alameda-county-housing/']::text[]) on conflict (id) do nothing;
insert into programs (id, regions, name, operator, kind, url, phone, tty, hours, what_it_is, waitlist_info, eligibility_info, vacancy_info, checked_on, sources) values ('la-aahr', array['la_city', 'la_county']::text[], 'Affordable & Accessible Housing Registry (AAHR)', 'Los Angeles Housing Department (LAHD), Accessible Housing Program', 'accessible_registry', 'https://accesshousingla.org/', '(213) 808-8550', '(213) 473-3231', null, 'The City of LA''s registry of affordable and accessible units in covered housing developments.', 'Register, then apply to open conventional waitlists or to an accessible-unit waitlist. You can get notified when properties open applications.', 'Each property has income and rent limits. The registry publishes current AMI income and rent limits.', 'Shows properties and whether applications or waitlists are open. That is not a promise of an immediate vacancy.', '2026-11-01', array['https://housing.lacity.gov/housing/how-do-i-find-accessible-rental-housing']::text[]) on conflict (id) do nothing;
insert into programs (id, regions, name, operator, kind, url, phone, tty, hours, what_it_is, waitlist_info, eligibility_info, vacancy_info, checked_on, sources) values ('la-lahd-properties', array['la_city', 'la_county']::text[], 'LAHD — Find our properties', 'Los Angeles Housing Department (LAHD)', 'property_map', 'https://housing.lacity.gov/housing/find-our-properties', null, null, null, 'A map of LAHD-supported affordable housing developments since 2003, plus a link to an affordable rental search.', 'Apply through the property or the registry. The map itself is not an application.', 'Set per property.', 'A list of properties, NOT of open units. Contact the property to ask about vacancies or waitlists.', '2026-11-01', array['https://housing.lacity.gov/housing/find-our-properties']::text[]) on conflict (id) do nothing;
insert into programs (id, regions, name, operator, kind, url, phone, tty, hours, what_it_is, waitlist_info, eligibility_info, vacancy_info, checked_on, sources) values ('la-county-hrc', array['la_city', 'la_county']::text[], 'LA County Housing Resource Center', 'Los Angeles County Development Authority (LACDA)', 'resource_center', 'https://housing.lacounty.gov/', '1-877-428-8844', '7-1-1', 'Mon–Fri, 6 a.m.–5 p.m. Pacific (English and Spanish)', 'Free search and listing of affordable, special-needs, accessible and emergency housing in LA County, with a toll-free call center.', 'Each listing explains how to apply.', 'Set per listing or program.', 'Listings are updated regularly, but each unit''s availability still needs to be confirmed with the owner or manager.', '2026-11-01', array['https://www.housing.lacounty.gov/About.html']::text[]) on conflict (id) do nothing;
insert into programs (id, regions, name, operator, kind, url, phone, tty, hours, what_it_is, waitlist_info, eligibility_info, vacancy_info, checked_on, sources) values ('211-la', array['la_city', 'la_county']::text[], '211 LA', '211 LA County', 'referral_line', 'https://211la.org/', '211', null, '24 hours, 7 days', 'Free referrals for shelter, housing help and other services in LA County.', 'Referrals, not applications.', 'Depends on the program you''re referred to.', 'Doesn''t list individual rental vacancies.', '2026-11-01', array['https://211la.org/']::text[]) on conflict (id) do nothing;
